import socket,subprocess,json
def execute(connection,interface):
    if connection.family!=socket.AF_INET:raise ValueError('IPv4 TCP only')
    connection.getpeername()
    if not isinstance(interface,str) or not interface or '\x00' in interface:raise ValueError('invalid interface')
    result=subprocess.run(['ip','-j','link','show','dev',interface],capture_output=True,text=True,check=True,timeout=2)
    rows=json.loads(result.stdout)
    if len(rows)!=1:raise ValueError('interface ambiguity')
    mtu=int(rows[0]['mtu']);mss=connection.getsockopt(socket.IPPROTO_TCP,socket.TCP_MAXSEG)
    return {'interface':interface,'mtu_bytes':mtu,'negotiated_mss_bytes':mss,'ipv4_tcp_base_header_bound':mtu-40,'within_base_bound':0<mss<=mtu-40}
```

原理补充：
MTU 限制链路上承载的网络层包大小，TCP MSS 描述单段 TCP 数据上限，还需扣除 IP/TCP 头并考虑封装和选项。隧道可能降低有效载荷空间。应测端到端路径和协商结果，不能因网卡 MTU=1500 就让应用每段发送1500字节 TCP 数据。

