import socket,subprocess,re
def execute(connection):
    if connection.family!=socket.AF_INET:raise ValueError('IPv4 TCP only')
    local=connection.getsockname();peer=connection.getpeername()
    output=subprocess.run(['ss','-H','-t','-i','-n','-O'],capture_output=True,text=True,check=True,timeout=2).stdout
    rows=[]
    for line in output.splitlines():
        fields=line.split()
        if len(fields)>=5 and fields[3]==local[0]+':'+str(local[1]) and fields[4]==peer[0]+':'+str(peer[1]):rows.append(line)
    if len(rows)!=1:raise ValueError('exact connection not found')
    def field(key):
        match=re.search(r'(?:^|\s)'+key+r':(\d+)(?:\s|$)',rows[0])
        if not match:raise ValueError('kernel did not expose '+key)
        return int(match.group(1))
    mss=field('mss');cwnd=field('cwnd');window=field('snd_wnd')
    return {'mss_bytes':mss,'cwnd_segments':cwnd,'cwnd_bytes':mss*cwnd,'peer_advertised_window_bytes':window,'window_bound_bytes':min(mss*cwnd,window)}
```

原理补充：
接收窗口表示对端可接纳的数据量，拥塞窗口由发送端根据网络反馈控制在途数据。可发送量受到二者及实际实现共同限制。零窗口常需检查接收端消费速度；网络拥塞则还要看丢包、RTT 和拥塞控制，不能把两个窗口混为一谈。

